import pytest

from bedrock_protocol import v898, v924, v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ClientBoundDataDrivenUIShowScreen{ScreenID: "my_screen", FormID: 300, DataInstanceID:
# protocol.Option[uint32](70000)}
SHOW = bytes.fromhex("096d795f73637265656e2c0100000170110100")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ClientBoundDataDrivenUIShowScreen{ScreenID: "", FormID: 1}
BARE = bytes.fromhex("000100000000")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ClientBoundDataDrivenUIShowScreen{FormID: 0xffffffff, DataInstanceID: protocol.Option[uint32](0xffffffff)}
MAXIMUM = bytes.fromhex("00ffffffff01ffffffff")

# generated by gophertunnel 0381a95:
# packet.ClientBoundDataDrivenUIShowScreen{ScreenID: "demo"}
V924 = bytes.fromhex("0464656d6f")

GOLDENS = (
    [
        pytest.param(
            v.ClientboundDataDrivenUIShowScreenPacket(screen_id="my_screen", form_id=300, data_instance_id=70000),
            SHOW,
            id=f"{v.__name__.rpartition('.')[2]}-with-ids",
        )
        for v in VERSIONS
    ]
    + [
        pytest.param(
            v.ClientboundDataDrivenUIShowScreenPacket(form_id=1), BARE, id=f"{v.__name__.rpartition('.')[2]}-bare"
        )
        for v in VERSIONS
    ]
    + [
        pytest.param(
            v.ClientboundDataDrivenUIShowScreenPacket(form_id=0xFFFFFFFF, data_instance_id=0xFFFFFFFF),
            MAXIMUM,
            id=f"{v.__name__.rpartition('.')[2]}-four-byte-ids",
        )
        for v in VERSIONS
    ]
    + [pytest.param(v924.ClientboundDataDrivenUIShowScreenPacket(screen_id="demo"), V924, id="v924-lone-screen-id")]
)


@pytest.mark.parametrize("version", [v924, *VERSIONS])
def test_clientbound_data_driven_ui_show_screen_is_packet_333(version):
    assert version.PACKETS[333] is version.ClientboundDataDrivenUIShowScreenPacket


def test_clientbound_data_driven_ui_show_screen_is_not_a_packet_at_898():
    assert 333 not in v898.PACKETS


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_data_driven_ui_show_screen_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_data_driven_ui_show_screen_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
